import React from 'react';
import { useDispatch } from 'react-redux';
import { Paper } from '@material-ui/core';
import { showToast } from 'actions/admin/auth';
import colors from 'config/colors';

// Print-ready files for Innobs staff to hand out to schools. They are served from innobs.com (the company site),
// so this page always opens the latest published version.
const MATERIALS = [
  {
    key: 'pamphlet',
    title: 'Scholae pamphlet',
    detail: 'Tri-fold A4 brochure: features, every module, roles, pricing and a demo QR code.',
    url: 'https://innobs.com/downloads/scholae-pamphlet.pdf',
  },
  {
    key: 'card',
    title: 'Innobs visiting card',
    detail: 'Business card (90 x 50 mm), front and back, with phone numbers, emails and a demo QR code.',
    url: 'https://innobs.com/downloads/innobs-visiting-card.pdf',
  },
];

const rowStyle = {
  display: 'flex',
  alignItems: 'center',
  flexWrap: 'wrap',
  gap: 16,
  padding: '16px 0',
  borderTop: '1px solid #e8e3f0',
};

const buttonStyle = {
  display: 'inline-block',
  padding: '8px 18px',
  borderRadius: 8,
  fontWeight: 700,
  fontSize: 13,
  cursor: 'pointer',
  textDecoration: 'none',
};

const MarketingMaterialsPage = () => {
  const dispatch = useDispatch();

  const copyLink = async url => {
    try {
      await navigator.clipboard.writeText(url);
      dispatch(showToast('Link copied', 'success'));
    } catch (err) {
      dispatch(
        showToast('Could not copy the link. Please copy it from the address bar after opening the file.', 'error')
      );
    }
  };

  return (
    <div className="content">
      <Paper elevation={0} style={{ padding: 20, border: '3px solid #e0e0e0' }}>
        <div className="card-category font-weight-bold mb-1">Marketing materials</div>
        <p style={{ color: '#6b778a', marginBottom: 12 }}>
          Print-ready files to give to schools. They open from innobs.com, so you always get the latest version.
        </p>
        {MATERIALS.map(item => (
          <div key={item.key} style={rowStyle}>
            <i className="fas fa-file-pdf" style={{ fontSize: 28, color: colors.accent }} />
            <div style={{ flex: '1 1 260px' }}>
              <div style={{ fontWeight: 700, color: colors.grey1 }}>{item.title}</div>
              <div style={{ color: '#6b778a', fontSize: 13 }}>{item.detail}</div>
            </div>
            <div style={{ display: 'flex', gap: 10 }}>
              <a
                href={item.url}
                target="_blank"
                rel="noopener noreferrer"
                style={{ ...buttonStyle, background: colors.accent, color: '#fff' }}>
                Open PDF
              </a>
              <button
                type="button"
                onClick={() => copyLink(item.url)}
                style={{
                  ...buttonStyle,
                  background: '#fff',
                  color: colors.accent,
                  border: `1px solid ${colors.accent}`,
                }}>
                Copy link
              </button>
            </div>
          </div>
        ))}
      </Paper>
    </div>
  );
};

export default MarketingMaterialsPage;
